import { drawingContentKey } from '@frade/draw/document'
/** Both editors export navigation dimensions; navigation/formatting is not a semantic edit. */
export function sameDiagramContent(path: string, left: string, right: string): boolean {
  if (left === right) return true
  if (path.toLowerCase().endsWith('.frade')) {
    try {
      return drawingContentKey(left) === drawingContentKey(right)
    } catch {
      return false
    } // Invalid drawings are never equivalent to different input bytes.
  }
  const parse = (xml: string) => {
    const doc = new DOMParser().parseFromString(xml, 'text/xml')
    if (doc.querySelector('parsererror')) return
    for (const model of doc.querySelectorAll('mxGraphModel')) {
      model.removeAttribute('dx')
      model.removeAttribute('dy')
    }
    return doc.documentElement
  }
  const a = parse(left),
    b = parse(right)
  return !!a && !!b && a.isEqualNode(b)
}

import { parseDocument, type DiagramDocument } from './schema'

export type DrawingPage = {
  id: string
  name: string
  graph: DiagramDocument['graph']
  viewport?: DiagramDocument['viewport']
}
export type MultipageDocument = {
  format: 'frade-draw'
  version: 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
}
export type DrawingDocument = DiagramDocument | MultipageDocument
export type DrawingState = {
  version: 1 | 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
  activeId: string
}

function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value))
    throw Error('Invalid drawing structure')
  return value as Record<string, unknown>
}
function name(value: unknown, message: string): string {
  if (typeof value !== 'string' || !value.trim()) throw Error(message)
  return value
}

/** Validate every graph before any editor/session replacement. The v1 API stays unchanged. */
export function parseDrawingDocument(value: unknown): DrawingDocument {
  const input = record(value)
  if (input.version !== 2) return parseDocument(value)
  if (input.format !== 'frade-draw') throw Error('Unsupported document format')
  const metadata = parseDocument({
    format: 'frade-draw',
    version: 1,
    metadata: input.metadata,
    graph: { nodes: [], edges: [] },
  }).metadata
  if (!Array.isArray(input.pages) || !input.pages.length) throw Error('Drawing needs a page')
  const ids = new Set<string>()
  const pages = input.pages.map((value) => {
    const page = record(value),
      id = name(page.id, 'Invalid page ID')
    if (ids.has(id)) throw Error('Duplicate page ID')
    ids.add(id)
    const parsed = parseDocument({
      format: 'frade-draw',
      version: 1,
      metadata,
      graph: page.graph,
      ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
    })
    return {
      id,
      name: name(page.name, 'Invalid page name'),
      graph: parsed.graph,
      ...(parsed.viewport === undefined ? {} : { viewport: parsed.viewport }),
    }
  })
  return { format: 'frade-draw', version: 2, metadata, pages }
}
export const serializeDrawingDocument = (value: DrawingDocument) =>
  JSON.stringify(parseDrawingDocument(value), null, 2)
export const deserializeDrawingDocument = (json: string) => parseDrawingDocument(JSON.parse(json))

export function pageState(value: unknown, firstName = 'Страница-1'): DrawingState {
  const document = parseDrawingDocument(value)
  const pages =
    document.version === 2
      ? document.pages
      : [
          {
            id: document.metadata.id + '/page-1',
            name: firstName,
            graph: document.graph,
            ...(document.viewport === undefined ? {} : { viewport: document.viewport }),
          },
        ]
  return {
    version: document.version,
    metadata: document.metadata,
    pages,
    activeId: pages[0].id,
  }
}
export function drawingDocument(state: DrawingState): DrawingDocument {
  if (state.version === 2)
    return {
      format: 'frade-draw',
      version: 2,
      metadata: state.metadata,
      pages: state.pages,
    }
  const page = state.pages[0]
  return {
    format: 'frade-draw',
    version: 1,
    metadata: state.metadata,
    graph: page.graph,
    ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
  }
}
export function semanticDrawing(value: DrawingDocument) {
  const parsed = parseDrawingDocument(value)
  if (parsed.version === 1) {
    return {
      format: parsed.format,
      version: parsed.version,
      metadata: parsed.metadata,
      graph: parsed.graph,
    }
  }
  return {
    ...parsed,
    pages: parsed.pages.map(({ id, name, graph }) => ({ id, name, graph })),
  }
}
/** Semantic dirty key: object formatting/order and navigation are not diagram edits. */
export function drawingContentKey(json: string): string {
  return JSON.stringify(semanticDrawing(deserializeDrawingDocument(json)), (_key, value) =>
    value && typeof value === 'object' && !Array.isArray(value)
      ? Object.fromEntries(
          Object.keys(value)
            .sort()
            .map((key) => [key, value[key]]),
        )
      : value,
  )
}
function pageIndex(state: DrawingState, id: string) {
  const index = state.pages.findIndex((page) => page.id === id)
  if (index < 0) throw Error('Page no longer exists')
  return index
}
function newPage(state: DrawingState, page: DrawingPage) {
  if (state.pages.some((current) => current.id === page.id)) throw Error('Duplicate page ID')
  const parsed = parseDrawingDocument({
    format: 'frade-draw',
    version: 2,
    metadata: state.metadata,
    pages: [page],
  }) as MultipageDocument
  return parsed.pages[0]
}
export function nextPageName(pages: DrawingPage[], numbered: (index: number) => string) {
  const names = new Set(pages.map((page) => page.name))
  let index = pages.length + 1
  while (names.has(numbered(index))) index++
  return numbered(index)
}
export function insertDrawingPage(state: DrawingState, value: DrawingPage): DrawingState {
  const page = newPage(state, value)
  return {
    ...state,
    version: 2,
    pages: [...state.pages, page],
    activeId: page.id,
  }
}
export function duplicateDrawingPage(
  state: DrawingState,
  sourceId: string,
  id: string,
  copyName: string,
): DrawingState {
  const index = pageIndex(state, sourceId),
    source = state.pages[index]
  const graph = structuredClone(source.graph)
  const mapped = new Map(graph.nodes.map((node) => [node.id, id + '/' + node.id]))
  for (const node of graph.nodes) node.id = mapped.get(node.id)!
  for (const edge of graph.edges) {
    edge.id = id + '/' + edge.id
    edge.source.nodeId = mapped.get(edge.source.nodeId)!
    edge.target.nodeId = mapped.get(edge.target.nodeId)!
  }
  const page = newPage(state, { id, name: copyName, graph })
  const pages = state.pages.slice()
  pages.splice(index + 1, 0, page)
  return { ...state, version: 2, pages, activeId: id }
}
export function renameDrawingPage(state: DrawingState, id: string, value: string): DrawingState {
  const index = pageIndex(state, id)
  if (!value.trim() || state.pages[index].name === value) return state
  return {
    ...state,
    version: 2,
    pages: state.pages.map((page, i) => (i === index ? { ...page, name: value } : page)),
  }
}
export function clearDrawingPages(state: DrawingState, replacement: DrawingPage): DrawingState {
  const page = newPage(state, replacement)
  return { ...state, version: 2, pages: [page], activeId: page.id }
}
export function removeDrawingPage(
  state: DrawingState,
  id: string,
  replacement: DrawingPage,
): DrawingState {
  const index = pageIndex(state, id)
  if (state.pages.length === 1) return clearDrawingPages(state, replacement)
  const pages = state.pages.filter((page) => page.id !== id)
  return {
    ...state,
    version: 2,
    pages,
    activeId: state.activeId === id ? pages[Math.min(index, pages.length - 1)].id : state.activeId,
  }
}
export function moveDrawingPage(
  state: DrawingState,
  id: string,
  destination: number,
): DrawingState {
  const index = pageIndex(state, id)
  if (!Number.isInteger(destination) || destination < 0 || destination >= state.pages.length)
    throw Error('Invalid page position')
  if (index === destination) return state
  const pages = state.pages.slice(),
    page = pages.splice(index, 1)[0]
  pages.splice(destination, 0, page)
  return { ...state, version: 2, pages }
}
export function sortDrawingPages(state: DrawingState, locale: string): DrawingState {
  const compare = new Intl.Collator(locale, {
    numeric: true,
    sensitivity: 'base',
  })
  const pages = state.pages.slice().sort((a, b) => compare.compare(a.name, b.name))
  return pages.every((page, i) => page === state.pages[i]) ? state : { ...state, version: 2, pages }
}

import type { Graph } from '@antv/x6'
import { graphToDocument, loadDocument } from '../document/graphAdapter'
import {
  pageState,
  drawingDocument,
  insertDrawingPage,
  duplicateDrawingPage,
  removeDrawingPage,
  renameDrawingPage,
  moveDrawingPage,
  sortDrawingPages,
  clearDrawingPages,
  parseDrawingDocument,
  type DrawingDocument,
  type DrawingState,
  type DrawingPage,
} from '../document/drawing'

export type DrawingSessionEvent = 'change' | 'page' | 'load' | 'readonly'
export type DrawingSession = ReturnType<typeof createDrawingSession>
type HistoryEntry = { before: DrawingState; after: DrawingState }
type Options = { firstPageName?: string; onError?(error: Error): void }

/** One stable X6 surface; semantic snapshots follow native committed history batches. */
export function createDrawingSession(graph: Graph, initial: unknown, options: Options = {}) {
  let data = pageState(initial, options.firstPageName),
    readonly = false,
    disposed = false,
    restoring = false,
    generation = 0
  const past: HistoryEntry[] = [],
    future: HistoryEntry[] = []
  const listeners = new Set<(event: DrawingSessionEvent) => void>()
  const original = {
    undo: graph.undo,
    redo: graph.redo,
    canUndo: graph.canUndo,
    canRedo: graph.canRedo,
  }
  const current = () => data.pages.find((page) => page.id === data.activeId)!
  const assertLive = () => {
    if (disposed) throw Error('Drawing session is closed')
  }
  const editable = () => {
    assertLive()
    if (readonly) throw Error('Drawing is read-only')
  }
  const notify = (event: DrawingSessionEvent) => {
    for (const listener of listeners) listener(event)
  }
  function capture() {
    assertLive()
    const { tx, ty } = graph.translate()
    const model = graphToDocument(graph, data.metadata, {
      zoom: graph.zoom(),
      pan: { x: tx, y: ty },
    })
    const page = current()
    const graphData =
      JSON.stringify(page.graph) === JSON.stringify(model.graph) ? page.graph : model.graph
    data = {
      ...data,
      pages: data.pages.map((p) =>
        p.id === page.id ? { ...page, graph: graphData, viewport: model.viewport } : p,
      ),
    }
    return data
  }
  function restore(next: DrawingState, force = false) {
    const old = current(),
      page = next.pages.find((p) => p.id === next.activeId)!
    const changedPage = old.id !== page.id
    const replace = force || changedPage || old.graph !== page.graph
    if (replace) {
      const selected = changedPage ? [] : graph.getSelectedCells().map((cell) => cell.id)
      restoring = true
      try {
        const model = loadDocument(graph, {
          format: 'frade-draw',
          version: 1,
          metadata: next.metadata,
          graph: page.graph,
          ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
        })
        next = {
          ...next,
          pages: next.pages.map((p) => (p.id === page.id ? { ...p, graph: model.graph } : p)),
        }
        if (selected.length)
          graph.select(
            selected.flatMap((id) => {
              const cell = graph.getCellById(id)
              return cell ? [cell] : []
            }),
          )
      } finally {
        restoring = false
      }
      generation++
    }
    data = next
    return replace
  }
  function mutate(operation: (state: DrawingState) => DrawingState) {
    editable()
    const before = capture(),
      next = operation(before)
    if (next === before) return
    const pageChanged = restore(next)
    past.push({ before, after: data })
    future.length = 0
    if (pageChanged) notify('page')
    notify('change')
  }
  function committed() {
    if (restoring || disposed) return
    // X6 records a provisional connection before both semantic terminals exist.
    // It is not a drawing command yet; flush/navigation still validate and reject it.
    if (graph.getEdges().some((edge) => !edge.getSourceCell() || !edge.getTargetCell())) return
    const before = data
    try {
      capture()
      if (current().graph === before.pages.find((p) => p.id === before.activeId)!.graph) return
      past.push({ before, after: data })
      future.length = 0
      notify('change')
    } catch (error) {
      if (!options.onError) throw error
      options.onError(error instanceof Error ? error : Error(String(error)))
    }
  }
  function replay(state: DrawingState) {
    // A history command is complete when its model AND replacement views are ready.
    // Keep the validated loader and documentRestore flag; restore normal scheduling afterwards.
    const asynchronous = graph.options.async
    graph.options.async = false
    try {
      return restore({ ...state, metadata: data.metadata })
    } finally {
      graph.options.async = asynchronous
    }
  }
  function undo() {
    editable()
    const entry = past.at(-1)
    if (!entry) return
    const changedPage = replay(entry.before)
    past.pop()
    future.push(entry)
    if (changedPage) notify('page')
    notify('change')
  }
  function redo() {
    editable()
    const entry = future.at(-1)
    if (!entry) return
    const changedPage = replay(entry.after)
    future.pop()
    past.push(entry)
    if (changedPage) notify('page')
    notify('change')
  }
  restore(data, true)
  capture()
  graph.on('history:add', committed)
  graph.undo = () => {
    undo()
    return graph
  }
  graph.redo = () => {
    redo()
    return graph
  }
  graph.canUndo = () => !readonly && past.length > 0
  graph.canRedo = () => !readonly && future.length > 0
  const empty = (id: string, name: string): DrawingPage => ({
    id,
    name,
    graph: { nodes: [], edges: [] },
  })
  return {
    view: () => ({
      activeId: data.activeId,
      pages: data.pages.map(({ id, name }) => ({ id, name })),
      canUndo: !readonly && past.length > 0,
      canRedo: !readonly && future.length > 0,
      readOnly: readonly,
    }),
    get generation() {
      return generation
    },
    get restoring() {
      return restoring
    },
    subscribe(listener: (event: DrawingSessionEvent) => void) {
      assertLive()
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    snapshot(): DrawingDocument {
      return parseDrawingDocument(drawingDocument(capture()))
    },
    load(value: unknown) {
      assertLive()
      const next = pageState(value, options.firstPageName)
      restore(next, true)
      capture()
      past.length = 0
      future.length = 0
      notify('load')
      return drawingDocument(data)
    },
    select(id: string) {
      assertLive()
      if (id === data.activeId) return
      if (!data.pages.some((page) => page.id === id)) throw Error('Page no longer exists')
      capture()
      restore({ ...data, activeId: id })
      notify('page')
    },
    insert: (id: string, name: string) =>
      mutate((state) => insertDrawingPage(state, empty(id, name))),
    duplicate: (source: string, id: string, name: string) =>
      mutate((state) => duplicateDrawingPage(state, source, id, name)),
    rename: (id: string, name: string) => mutate((state) => renameDrawingPage(state, id, name)),
    remove: (id: string, replacementId: string, name: string) =>
      mutate((state) => removeDrawingPage(state, id, empty(replacementId, name))),
    move: (id: string, index: number) => mutate((state) => moveDrawingPage(state, id, index)),
    sort: (locale: string) => mutate((state) => sortDrawingPages(state, locale)),
    clear: (id: string, name: string) =>
      mutate((state) => clearDrawingPages(state, empty(id, name))),
    setName(name: string) {
      editable()
      if (!name.trim()) throw Error('Document name must not be empty.')
      data = { ...data, metadata: { ...data.metadata, name: name.trim() } }
      notify('change')
    },
    extract(id: string, documentId: string) {
      capture()
      const page = data.pages.find((p) => p.id === id)
      if (!page) throw Error('Page no longer exists')
      return parseDrawingDocument({
        format: 'frade-draw',
        version: 2,
        metadata: { id: documentId, name: page.name },
        pages: [page],
      })
    },
    setReadOnly(value: boolean) {
      assertLive()
      if (readonly !== value) {
        readonly = value
        notify('readonly')
      }
    },
    undo,
    redo,
    dispose() {
      if (disposed) return
      disposed = true
      graph.off('history:add', committed)
      listeners.clear()
      Object.assign(graph, original)
    },
  }
}

export type Point = { x: number; y: number }
export const diagramShapes = ['rect', 'rounded-rect', 'ellipse', 'diamond', 'text'] as const
export type DiagramShape = (typeof diagramShapes)[number]
export const styleKeys = [
  'fill',
  'stroke',
  'strokeWidth',
  'strokeDasharray',
  'opacity',
  'fillOpacity',
  'strokeOpacity',
  'rx',
  'ry',
  'fontSize',
  'fontFamily',
  'fontWeight',
  'fontStyle',
  'textAnchor',
] as const
export type DiagramStyle = Partial<Record<(typeof styleKeys)[number], string | number>>
export type Attachment = (
  { mode: 'floating'; nodeId: string } | { mode: 'fixed'; nodeId: string; portId: string }
) & { offset?: Point }
export type DiagramPort = Point & { id: string }
export type RepositoryNodeReference = { objectId: string; sourceId?: string }
export type DiagramShadow = { color: string; opacity: number; dx: number; dy: number; blur: number }
export type DiagramNode = {
  shadow?: DiagramShadow
  repositoryRef?: RepositoryNodeReference
  id: string
  shape: DiagramShape
  x: number
  y: number
  width: number
  height: number
  label: string
  style?: DiagramStyle
  labelStyle?: DiagramStyle
  ports?: DiagramPort[]
}
export type DiagramEdge = {
  labelPosition?: { distance: number; offset: Point }
  bundle?: { kind: 'empty'; integrationFlowRefs?: { repositoryId: string; objectId: string }[] }
  id: string
  source: Attachment
  target: Attachment
  constraints?: Array<{ axis: 'x' | 'y'; coordinate: number; order: number }>
  vertices?: Point[]
  style?: DiagramStyle
  router?: 'normal' | 'manhattan'
  targetMarker?: { name: 'classic' | 'block' | 'diamond' | 'circle'; size: number } | null
}
export interface DiagramDocument {
  format: 'frade-draw'
  version: 1
  metadata: { id: string; name: string }
  graph: { nodes: DiagramNode[]; edges: DiagramEdge[] }
  viewport?: { zoom: number; pan: Point }
}

function record(value: unknown, message: string): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error(message)
  return value as Record<string, unknown>
}
function text(value: unknown, message: string): string {
  if (typeof value !== 'string' || !value.trim()) throw new Error(message)
  return value
}
function finite(value: unknown, message: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(message)
  return value
}
function point(value: unknown, message: string): Point {
  const p = record(value, message)
  return { x: finite(p.x, message), y: finite(p.y, message) }
}
function style(value: unknown): DiagramStyle | undefined {
  if (value === undefined) return undefined
  const input = record(value, 'Invalid style'),
    result: DiagramStyle = {}
  for (const [key, val] of Object.entries(input)) {
    if (
      !(styleKeys as readonly string[]).includes(key) ||
      !(
        (typeof val === 'number' && Number.isFinite(val)) ||
        (typeof val === 'string' &&
          val.length <= 200 &&
          !/[<>\\]|url\s*\(|expression\s*\(/i.test(val))
      )
    ) {
      throw new Error('Invalid style')
    }
    result[key as (typeof styleKeys)[number]] = val as string | number
  }
  return result
}
function attachment(value: unknown): Attachment {
  const input = record(value, 'Invalid edge')
  const nodeId = text(input.nodeId, 'Invalid edge')
  let result: Attachment
  if (input.mode === 'floating') result = { mode: 'floating', nodeId }
  else if (input.mode === 'fixed')
    result = { mode: 'fixed', nodeId, portId: text(input.portId, 'Invalid edge') }
  else throw new Error('Invalid edge')
  if (input.offset !== undefined) result.offset = point(input.offset, 'Invalid terminal offset')
  return result
}

export function parseDocument(value: unknown): DiagramDocument {
  const input = record(value, 'Document must be an object')
  if (input.format !== 'frade-draw' && input.format !== 'frade-designer')
    throw new Error('Unsupported document format')
  if (input.version !== 1) throw new Error('Unsupported document version')
  const metadata = record(input.metadata, 'Invalid document structure')
  const graph = record(input.graph, 'Invalid document structure')
  if (!Array.isArray(graph.nodes) || !Array.isArray(graph.edges))
    throw new Error('Invalid document structure')
